text:
{
  "title_novice": "Уравнение пьезопроводности: смысл членов",
  "summary": [
    {"text": "Давление в пласте меняется во времени по уравнению пьезопроводности.", "claims": ["c1"]},
    {"text": "Скорость изменения давления равна коэффициенту ϰ, умноженному на сумму вторых производных давления по координатам.", "claims": ["c2"]},
    {"text": "По форме это уравнение совпадает с классическим уравнением теплопроводности.", "claims": ["c3"]}
  ],
  "claims": [
    {"key": "c1", "text": "Движение слабосжимаемой жидкости в упругом пласте описывается уравнением пьезопроводности для давления p.", "kind": "assumption", "unit_id": "u-039-589339", "page": 39, "quote": "Это движение (см. § 1.4) описывается уравнением нъезопроводности для давления $p$", "numbers": [], "question": null},
    {"key": "c2", "text": "Скорость изменения давления по времени равна ϰ, умноженному на сумму вторых производных давления по x, y, z.", "kind": "inference", "unit_id": "u-039-b654f4", "page": 39, "quote": "\\partial p/\\partial t = \\varkappa (\\partial^2 p/\\partial x^2 + \\partial^2 p/\\partial y^2 + \\partial^2 p/\\partial z^2) \\equiv \\varkappa \\Delta p", "numbers": [], "question": null},
    {"key": "c3", "text": "Уравнение пьезопроводности по форме совпадает с классическим уравнением теплопроводности.", "kind": "observation", "unit_id": "u-039-2d535f", "page": 39, "quote": "по форме совпадающим с классическим уравнением теплопроводности.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Слева стоит скорость изменения давления по времени, ∂p/∂t. Справа стоит ϰ, умноженный на Δp.", "claims": ["c2"], "hypothesis": false},
    {"text": "Δp — сумма вторых производных давления по трём координатам. Так записан оператор Лапласа.", "claims": ["c2"], "hypothesis": false},
    {"text": "Вторая производная показывает, насколько распределение давления изогнуто в данной точке.", "claims": [], "hypothesis": true},
    {"text": "Поэтому давление меняется там, где его распределение изогнуто.", "claims": [], "hypothesis": true},
    {"text": "При одинаковой кривизне большее ϰ даёт большую скорость изменения давления. Это видно из вида формулы.", "claims": ["c2"], "hypothesis": false},
    {"text": "Коэффициент ϰ задаёт, как быстро давление выравнивается. Это пояснение методиста, в тексте узла его нет.", "claims": [], "hypothesis": true},
    {"text": "Форма уравнения совпадает с классическим уравнением теплопроводности.", "claims": ["c3"], "hypothesis": false},
    {"text": "В уравнении первая производная по времени, а вторых производных по времени нет.", "claims": ["c2"], "hypothesis": false},
    {"text": "Поэтому оно описывает выравнивание, похожее на диффузию, а не волну, бегущую с постоянной скоростью.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Перед решением задачи смотрят на вид уравнения: какие производные входят и какие величины заданы.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Уравнение записано для слабосжимаемой жидкости в упругом пласте; другие случаи в этом узле не рассмотрены.", "claims": ["c1"], "hypothesis": false},
    {"text": "В записи (II.83) ϰ стоит множителем перед производными и не записан как функция координат или времени.", "claims": ["c2"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Почему теплопроводность — удобная аналогия", "text": "Тепло тоже растекается от горячего места и выравнивает температуру. Давление здесь описывается уравнением той же формы.", "claims": [], "hypothesis": true},
    {"title": "Почему звук здесь не подходит", "text": "Звук распространяется волной с постоянной скоростью и содержит вторую производную по времени. В формуле (II.83) такой производной нет.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Уравнение применимо к слабосжимаемой жидкости в упругом пласте.", "claims": ["c1"]}
  ],
  "terms_defined": [
    {"term": "уравнение пьезопроводности", "term_en": "piezoconductivity equation", "abbr": "", "definition": "Уравнение, описывающее изменение давления p во времени и в пространстве пласта; вид (II.83).", "claims": ["c1", "c2"]},
    {"term": "коэффициент пьезопроводности", "term_en": "piezoconductivity coefficient", "abbr": "", "definition": "Коэффициент ϰ в формуле (II.83), стоящий перед оператором Лапласа. Единица — квадрат длины на время (см. узел n12).", "claims": ["c2"]},
    {"term": "уравнение теплопроводности", "term_en": "heat conduction equation", "abbr": "", "definition": "Классическое уравнение, по форме совпадающее с уравнением (II.83). В тексте узла сказано только о сходстве формы.", "claims": ["c3"]},
    {"term": "вязкость", "term_en": "viscosity", "abbr": "", "definition": "Внутреннее трение жидкости при её течении. В уравнении (II.83) вязкость не записана отдельно.", "claims": ["c2"]},
    {"term": "оператор Лапласа", "term_en": "Laplace operator", "abbr": "Δ", "definition": "Сумма вторых производных по координатам x, y, z. В формуле (II.83) записан как Δp.", "claims": ["c2"]},
    {"term": "производная", "term_en": "derivative", "abbr": "", "definition": "Скорость изменения величины при изменении другой величины, например времени. Вторая производная — скорость изменения этой скорости.", "claims": ["c2"]}
  ],
  "terms_used": [
    "нестационарная фильтрация",
    "упругий режим",
    "слабосжимаемая жидкость",
    "упруго деформируемый пласт",
    "пласт",
    "давление",
    "вторая производная"
  ],
  "formulas": [
    {
      "unit_id": "u-039-b654f4",
      "label": "(II.83)",
      "latex": "\\partial p/\\partial t = \\varkappa (\\partial^2 p/\\partial x^2 + \\partial^2 p/\\partial y^2 + \\partial^2 p/\\partial z^2) \\equiv \\varkappa \\Delta p",
      "meaning": "Уравнение пьезопроводности: скорость изменения давления по времени равна ϰ, умноженному на сумму вторых производных давления по координатам.",
      "variables": [
        {"symbol": "p", "meaning": "давление в жидкости пласта", "unit": "в тексте узла не указана"},
        {"symbol": "t", "meaning": "время", "unit": "в тексте узла не указана"},
        {"symbol": "x, y, z", "meaning": "координаты точки пласта", "unit": "единица длины не указана в тексте узла"},
        {"symbol": "ϰ", "meaning": "коэффициент пьезопроводности", "unit": "квадрат длины на время (см. узел n12)"},
        {"symbol": "Δ", "meaning": "оператор Лапласа, сумма вторых производных по x, y, z", "unit": "единица p, делённая на квадрат единицы длины"}
      ]
    }
  ],
  "tables": [],
  "figures": [],
  "worked_examples": [],
  "book_problems": [],
  "misconception": {
    "pack_id": "M16",
    "wrong": "Давление в пласте расходится с постоянной скоростью, как звук: фронт идёт с одной и той же скоростью.",
    "right": "Давление описывает уравнение с первой производной по времени и вторыми по координатам. Такая запись задаёт выравнивание, а не бегущую волну.",
    "claims": ["c2"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Значения давления p в точках пласта с координатами x, y, z и в моменты времени t.", "claims": ["c2"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Скорость изменения давления по времени в каждой точке пласта; связана с кривизной распределения давления.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Вид уравнения верен только для слабосжимаемой жидкости в упругом пласте.", "claims": ["c1"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Выравнивание давления похоже на выравнивание нагрузки между соседними узлами кластера: пик постепенно растекается, а не мгновенно переносится. Гипотеза методиста.",
    "breaks_where": "В кластере узлы дискретны и обмен идёт по каналам. Здесь среда непрерывна, и выравнивание задаёт коэффициент ϰ; сходство только в характере растекания.",
    "hypothesis": true
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Без понимания, что давление выравнивается по диффузионному закону, не читаются кривые изменения давления и решения следующих узлов."
  },
  "inefficiency": {
    "inputs": [
      "значения давления p в точках пласта и в моменты времени t",
      "коэффициент ϰ, который нужно узнать или задать"
    ],
    "manual_steps": [
      "записать, какие производные входят в уравнение, и какие величины известны"
    ],
    "judgment_points": [
      "решить, можно ли считать жидкость слабосжимаемой и пласт упругим"
    ],
    "time": [
      "разбор уравнения и выбор ϰ занимают время, если данных мало"
    ],
    "typical_errors": [
      "принять уравнение за волновое и ожидать постоянной скорости распространения давления",
      "считать ϰ постоянной величиной без проверки условий"
    ]
  },
